  host.innerHTML=`<article class="cc-card cc-tree-detail"><div class="cc-row cc-between"><h3>${esc(s.name)}</h3>${button('Fermer','close')}</div>${art(s.id)}${pendingPanel(s,t)}<p>${t.verses.length} / ${s.count} versets validés</p><progress class="${(t.pendingVerses||[]).length?'cc-pending-progress':''}" max="100" value="${visibleGrowth(t,s.count)}"></progress>${t.completedAt?`<p>🌸 Sourate validée par ${esc(t.teacher)}<br>${esc(nameDate(t.completedAt))}</p>`:'<p>L’arbre grandit après la validation du professeur.</p>'}<div class="cc-next"><strong>🌱 Prochaine étape</strong><p>${next?`Apprendre ${range(next,Math.min(next+1,s.count))}.`:'Tous les versets sont validés. Tu peux revoir cette sourate quand tu veux.'}</p></div>${passage?`<div class="cc-assignment"><strong>💧 La maîtresse te propose de revoir ${range(passage.from,passage.to)}</strong>${passage.note?`<p>${esc(passage.note)}</p>`:''}<small>${esc(passage.author)} · ${esc(nameDate(passage.at))}</small>${studentView?`<div class="cc-row">${button(`Écouter ${range(passage.from,passage.to)}`,'practice-assigned',s.id,true)}${button('J’ai révisé','reviewed')}</div>`:''}</div>`:due(t)?'<p class="cc-note">💧 Un petit moment de révision est conseillé.</p>':''}<div class="cc-row">${studentView?button('Écouter et répéter','practice',s.id)+button(t.requested?'Demande envoyée ✓':'Je veux réciter','request')+button('Placer / déplacer mon arbre','move'):''}</div>${!studentView?`<form data-form="validate" class="cc-teacher-form"><h4>Valider après la récitation</h4><p>${t.requested?'🔔 Cet élève souhaite réciter.':'Choisissez le passage réussi après avoir écouté l’élève.'}</p><div class="cc-row"><label>Du verset<input name="from" type="number" min="1" max="${s.count}" value="1" required></label><label>Au verset<input name="to" type="number" min="1" max="${s.count}" value="${Math.min(5,s.count)}" required></label><button class="cc-primary">Valider le passage</button></div></form><p>${button('Valider toute la sourate','complete')}</p><form data-form="review" class="cc-teacher-form"><h4>Conseiller un passage à revoir</h4><div class="cc-row"><label>Du verset<input name="from" type="number" min="1" max="${s.count}" value="${next||1}" required></label><label>Au verset<input name="to" type="number" min="1" max="${s.count}" value="${Math.min((next||1)+1,s.count)}" required></label></div><label>Votre consigne personnelle<textarea name="note" maxlength="1500" placeholder="Ex. Maryam, reprends les versets 5 et 6 tranquillement…"></textarea></label><p><button class="cc-primary">Envoyer ce passage</button></p></form><form data-form="message" class="cc-teacher-form"><h4>Écrire une appréciation</h4><label>Votre message personnalisé<textarea name="message" maxlength="1500" required placeholder="Écrivez votre message pour cet élève…"></textarea></label><p><button class="cc-primary">Déposer le message sur l’arbre</button></p></form>`:''}<section class="cc-history"><h4>Historique de cet arbre</h4>${timeline}</section><div id="cc-practice"></div></article>`;
  if(!studentView)host.querySelector('.cc-history')?.insertAdjacentHTML('beforebegin',`<form data-form="verse-comment" class="cc-teacher-form cc-verse-comment-form"><h4>Commenter un verset précis</h4><p>Ce commentaire apparaîtra directement sous le verset. L’appréciation globale reste disponible.</p><label>Verset concerné<input name="verse" type="number" min="1" max="${s.count}" value="${next||1}" required></label><label>Commentaire écrit <span class="cc-optional">facultatif si vous ajoutez un audio</span><textarea name="message" maxlength="1500" placeholder="Ex. Reprends doucement ce mot…"></textarea></label><label class="cc-audio-picker">🎙️ Message audio <span class="cc-optional">facultatif</span><input name="audio" type="file" accept="audio/*" capture></label><small>Sur téléphone, vous pouvez enregistrer votre voix. Sur ordinateur, choisissez un fichier audio.</small><p><button class="cc-primary">Ajouter sous ce verset</button></p></form>`);
